contract InvMutTest {
    C c;
    constructor() { c = new C(address(this), 0); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(uint256 amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        require(address(this).balance >= amount);
        c.OpenToThePublic(); if (__ESBMC_reverted()) return;
        uint256 balanceBefore = c.ethBalance(); if (__ESBMC_reverted()) return;
        bool reverted;
        c.donate{value: amount}(); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }
        assert(
            !reverted
            && c.ethBalance() == balanceBefore
            && c.winnersPot() == c.ethBalance() / 2
            && !c.hasPlayerWagered(address(this))
        );
    }
    receive() external payable {}
}

